import type { TemplateContext } from '../types';

export function frontendReadme(ctx: TemplateContext): string {
  return [
    `# ${ctx.contract.projectName}`,
    '',
    'Generated by DevFlow.',
    '',
    '## Quick start',
    '',
    '```bash',
    'npm install',
    'npm run dev',
    '```',
    '',
    'Open http://localhost:3000 in your browser.',
    '',
    '## Project structure',
    '',
    '```',
    '.',
    '├── src/',
    '│   ├── app/',
    '│   │   ├── layout.tsx        # Root layout',
    '│   │   └── page.tsx          # Main page',
    '│   ├── components/',
    '│   │   └── ui/',
    '│   │       ├── Button.tsx',
    '│   │       └── Card.tsx',
    '│   └── styles/',
    '│       └── globals.css',
    '├── package.json',
    '├── next.config.ts',
    '├── postcss.config.mjs',
    '├── tsconfig.json',
    '└── README-frontend.md',
    '```',
    '',
    '## Available scripts',
    '',
    '| Command | Description |',
    '|---------|-------------|',
    '| `npm run dev` | Start development server |',
    '| `npm run build` | Production build |',
    '| `npm run start` | Start production server |',
    '',
    '## Tech stack',
    '',
    '- **Framework:** Next.js 16',
    '- **Language:** TypeScript',
    '- **Styling:** Tailwind CSS v4',
    '',
    '## Features',
    '',
    ...ctx.contract.requirements.features.map((f) => `- ${f}`),
    '',
  ].join('\n');
}
